//! SCAN.POLY.MULTI.OVLP acceptance tests. Scans and expected per-point results are in
//! `fixtures/scan/poly/*.ovlp.txt`, written by the independent Python reference
//! `fixtures/scan/poly/make_ovlp_fixtures.py` (brute force over all point pairs, no index and
//! no prefilter); nothing here was generated by running this crate. Results are compared
//! exactly. AC-1 and AC-2 are also checked against their own hand labels (strip in and out,
//! the two wall faces). AC-3 (chunked versus in-memory inputs) needs GEO.OOC, which is above
//! this kernel crate's layer, so it is in `crates/fid-geo-ooc/tests/scan_overlap.rs`.
#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)]

use fid_geo_index::Neighbour;
use fid_geo_types::{AttributeSet, FrameRef, PointBuffer, PointCloud};
use fid_scan_poly::{
    detect_overlap, MatchRule, MemoryScan, OverlapMap, OverlapSets, PointStatus, PolyError, ScanPoint, ScanView, MAX_D,
    MIN_D,
};

fn read(name: &str) -> String {
    std::fs::read_to_string(format!("{}/fixtures/scan/poly/{name}", fid_testkit::WORKSPACE_ROOT)).unwrap()
}

fn f(s: &str) -> f64 {
    s.parse().unwrap()
}

fn frame() -> FrameRef {
    FrameRef::from_bytes([7u8; 16])
}

struct Point {
    p: [f64; 3],
    n: [f64; 3],
    valid: bool,
    status: PointStatus,
    set: Vec<u32>,
}

struct Case {
    d: f64,
    scans: Vec<Vec<Point>>,
    pairs: Vec<(u32, u32, u64)>,
    summary: Vec<[u64; 5]>,
}

fn status(s: &str) -> PointStatus {
    match s {
        "overlapping" => PointStatus::Overlapping,
        "nothing_within_d" => PointStatus::NothingWithinD,
        "normals_incompatible" => PointStatus::NormalsIncompatible,
        other => panic!("status {other}"),
    }
}

fn load(case: &str) -> Case {
    let text = read(&format!("{case}.ovlp.txt"));
    let mut lines = text.lines().filter(|l| !l.starts_with('#'));
    let mut next = || lines.next().unwrap().to_string();
    assert_eq!(next(), format!("case {case}"));
    let d = f(next().strip_prefix("d ").unwrap());
    let s: usize = next().strip_prefix("scans ").unwrap().parse().unwrap();
    let mut scans = Vec::new();
    for i in 0..s {
        let head = next();
        let n: usize = head.strip_prefix(&format!("scan {i} points ")).unwrap().parse().unwrap();
        let mut pts = Vec::new();
        for _ in 0..n {
            let l = next();
            let t: Vec<&str> = l.split_whitespace().collect();
            assert_eq!(t.len(), 9, "{case}: {l}");
            let set = if t[8] == "-" { Vec::new() } else { t[8].split(',').map(|j| j.parse().unwrap()).collect() };
            pts.push(Point {
                p: [f(t[0]), f(t[1]), f(t[2])],
                n: [f(t[3]), f(t[4]), f(t[5])],
                valid: t[6] == "1",
                status: status(t[7]),
                set,
            });
        }
        scans.push(pts);
    }
    let m: usize = next().strip_prefix("pairs ").unwrap().parse().unwrap();
    let pairs = (0..m)
        .map(|_| {
            let l = next();
            let t: Vec<u64> = l.split_whitespace().map(|v| v.parse().unwrap()).collect();
            (t[0] as u32, t[1] as u32, t[2])
        })
        .collect();
    assert_eq!(next(), "summary");
    let summary = (0..s)
        .map(|i| {
            let l = next();
            let t: Vec<u64> = l.split_whitespace().map(|v| v.parse().unwrap()).collect();
            assert_eq!(t[0], i as u64);
            [t[1], t[2], t[3], t[4], t[5]]
        })
        .collect();
    Case { d, scans, pairs, summary }
}

fn cloud(pts: &[Point]) -> (PointCloud, Vec<bool>) {
    let buf = PointBuffer::new(
        pts.iter().map(|p| p.p[0]).collect(),
        pts.iter().map(|p| p.p[1]).collect(),
        pts.iter().map(|p| p.p[2]).collect(),
    );
    let attrs = AttributeSet {
        normal: Some([
            pts.iter().map(|p| p.n[0]).collect(),
            pts.iter().map(|p| p.n[1]).collect(),
            pts.iter().map(|p| p.n[2]).collect(),
        ]),
        ..AttributeSet::default()
    };
    (PointCloud::new(frame(), buf, attrs).unwrap(), pts.iter().map(|p| p.valid).collect())
}

fn run(c: &Case) -> OverlapMap {
    let clouds: Vec<(PointCloud, Vec<bool>)> = c.scans.iter().map(Vec::as_slice).map(cloud).collect();
    let views: Vec<MemoryScan<'_>> = clouds.iter().map(|(cl, v)| MemoryScan::new(cl, v).unwrap()).collect();
    let dyns: Vec<&dyn ScanView> = views.iter().map(|v| v as &dyn ScanView).collect();
    detect_overlap(&dyns, c.d).unwrap()
}

/// Compares every per-point result, the pairs and the summaries with the reference.
fn check(name: &str, c: &Case, m: &OverlapMap) {
    assert_eq!(m.d, c.d);
    assert_eq!(m.scans.len(), c.scans.len());
    for (i, (got, want)) in m.scans.iter().zip(&c.scans).enumerate() {
        assert_eq!(got.sets.len(), want.len(), "{name} scan {i}");
        assert_eq!(got.status.len(), want.len());
        assert_eq!(got.rule.len(), want.len());
        for (k, w) in want.iter().enumerate() {
            assert_eq!(got.sets.scans_of(k).unwrap(), w.set, "{name} scan {i} point {k}");
            assert_eq!(got.status[k], w.status, "{name} scan {i} point {k}");
            let rule = if w.valid { MatchRule::Normal } else { MatchRule::AnyPoint };
            assert_eq!(got.rule[k], rule, "{name} scan {i} point {k}");
            for j in 0..c.scans.len() as u32 {
                assert_eq!(got.sets.contains(k, j), Some(w.set.contains(&j)));
            }
        }
        let s = got.summary;
        let want_s = c.summary[i];
        assert_eq!(
            [s.points, s.overlapping, s.nothing_within_d, s.normals_incompatible, s.without_normal],
            want_s,
            "{name} summary {i}"
        );
    }
    let got_pairs: Vec<(u32, u32, u64)> = m.pairs.iter().map(|p| (p.scan, p.other, p.points)).collect();
    assert_eq!(got_pairs, c.pairs, "{name} pairs");
    for i in 0..c.scans.len() as u32 {
        assert_eq!(m.pair_count(i, i), None);
        for j in 0..c.scans.len() as u32 {
            if i != j {
                let want = c.pairs.iter().find(|p| p.0 == i && p.1 == j).map_or(0, |p| p.2);
                assert_eq!(m.pair_count(i, j), Some(want));
            }
        }
    }
    assert_eq!(m.pair_count(0, c.scans.len() as u32), None);
}

#[test]
fn ac1_two_sheets_overlap_on_the_strip() {
    let c = load("two_sheets_overlap");
    assert_eq!(c.d, 0.0003);
    let m = run(&c);
    check("two_sheets_overlap", &c, &m);
    // Hand labels: the strip is x in [10, 30] mm, where both scans measured the plate.
    let (mut inside, mut outside) = (0, 0);
    for (i, scan) in c.scans.iter().enumerate() {
        for (k, p) in scan.iter().enumerate() {
            let x = p.p[0];
            let r = &m.scans[i];
            if (0.010..=0.030).contains(&x) {
                inside += 1;
                assert_eq!(r.status[k], PointStatus::Overlapping, "scan {i} x {x}");
                assert_eq!(r.sets.scans_of(k).unwrap(), vec![1 - i as u32]);
            }
            if x < 0.010 - c.d || x > 0.030 + c.d {
                outside += 1;
                assert_eq!(r.status[k], PointStatus::NothingWithinD, "scan {i} x {x}");
                assert!(r.sets.scans_of(k).unwrap().is_empty());
            }
        }
    }
    assert!(inside > 600 && outside > 300, "{inside} {outside}");
    assert!(matches!(m.scans[0].sets, OverlapSets::Bits(_)));
}

#[test]
fn ac2_thin_wall_faces_do_not_overlap() {
    let c = load("thin_wall_two_scans");
    assert!(c.d > 0.001, "d exceeds the wall thickness, so only the normals separate the faces");
    let m = run(&c);
    check("thin_wall_two_scans", &c, &m);
    let mut back = 0;
    for (k, p) in c.scans[1].iter().enumerate() {
        if p.p[2] > 0.0005 {
            back += 1;
            assert_eq!(m.scans[1].status[k], PointStatus::NormalsIncompatible);
            assert!(m.scans[1].sets.scans_of(k).unwrap().is_empty());
        }
    }
    assert_eq!(back, 80);
    for (k, p) in c.scans[0].iter().enumerate() {
        if p.p[0] > 0.0042 {
            assert_eq!(m.scans[0].status[k], PointStatus::NormalsIncompatible, "front point {k}");
        }
    }
}

#[test]
fn normal_rules_and_ties() {
    let c = load("normals_mix");
    let m = run(&c);
    check("normals_mix", &c, &m);
    // The empty fourth scan is reported, not dropped.
    assert_eq!(m.scans[3].summary.points, 0);
    assert!(m.scans[3].sets.is_empty());
}

#[test]
fn more_than_64_scans_use_sorted_lists() {
    let c = load("many_scans");
    assert_eq!(c.scans.len(), 66);
    let m = run(&c);
    check("many_scans", &c, &m);
    assert!(matches!(m.scans[0].sets, OverlapSets::Lists { .. }));
    assert_eq!(m.scans[33].sets.scans_of(1).unwrap(), vec![0, 64, 65]);
}

// ------------------------------------------------------------------ errors

fn small() -> (PointCloud, Vec<bool>) {
    let pts =
        [Point { p: [0.0; 3], n: [0.0, 0.0, 1.0], valid: true, status: PointStatus::NothingWithinD, set: vec![] }];
    cloud(&pts)
}

fn invalid_name(e: PolyError) -> &'static str {
    match e {
        PolyError::InvalidParameter { name, .. } => name,
        other => panic!("not invalid_parameter: {other:?}"),
    }
}

#[test]
fn parameter_and_scan_checks() {
    let (cl, v) = small();
    let a = MemoryScan::new(&cl, &v).unwrap();
    let b = MemoryScan::new(&cl, &v).unwrap();
    let two: [&dyn ScanView; 2] = [&a, &b];
    for d in [0.0, -1.0, f64::NAN, f64::INFINITY, MIN_D / 2.0, MAX_D * 2.0] {
        let e = detect_overlap(&two, d).unwrap_err();
        assert_eq!(e.code(), "scan.poly.invalid_parameter");
        assert_eq!(invalid_name(e), "d");
    }
    assert!(detect_overlap(&two, MIN_D).is_ok());
    assert!(detect_overlap(&two, MAX_D).is_ok());
    assert_eq!(invalid_name(detect_overlap(&two[..1], 1e-3).unwrap_err()), "scans");
    assert_eq!(invalid_name(detect_overlap(&[], 1e-3).unwrap_err()), "scans");

    let other = PointCloud::new(FrameRef::from_bytes([8u8; 16]), cl.buffer().clone(), cl.attributes().clone()).unwrap();
    let c = MemoryScan::new(&other, &v).unwrap();
    assert_eq!(invalid_name(detect_overlap(&[&a, &c], 1e-3).unwrap_err()), "scans.frame");

    assert_eq!(invalid_name(MemoryScan::new(&cl, &[]).unwrap_err()), "valid");
    let bare = PointCloud::from_points(frame(), &[[0.0; 3]]).unwrap();
    assert_eq!(invalid_name(MemoryScan::new(&bare, &[true]).unwrap_err()), "cloud.normal");
    // A cloud without normals is fine when no point claims one (REQ-002 applies to all).
    let bare_view = MemoryScan::new(&bare, &[false]).unwrap();
    let m = detect_overlap(&[&a, &bare_view], 1e-3).unwrap();
    assert_eq!(m.scans[1].rule, vec![MatchRule::AnyPoint]);
    assert_eq!(m.scans[1].sets.scans_of(0).unwrap(), vec![0]);
    assert_eq!(m.scans[0].status, vec![PointStatus::NormalsIncompatible]);
}

/// A view with hand-set points and a configurable (possibly broken) radius query.
struct Fake {
    pts: Vec<ScanPoint>,
    mode: Mode,
}

#[derive(Clone, Copy)]
enum Mode {
    BruteForce,
    ExtraFarHit,
    OutOfRangeHit,
    Fails,
}

impl ScanView for Fake {
    fn frame(&self) -> FrameRef {
        frame()
    }
    fn point_count(&self) -> u64 {
        self.pts.len() as u64
    }
    fn point(&self, i: u64) -> Result<ScanPoint, PolyError> {
        self.pts.get(i as usize).copied().ok_or(PolyError::Inconsistent)
    }
    fn radius(&self, x: [f64; 3], r: f64) -> Result<Vec<Neighbour>, PolyError> {
        let mut out: Vec<Neighbour> = self
            .pts
            .iter()
            .enumerate()
            .map(|(i, p)| Neighbour { index: i as u64, dist2: fid_geo_index::dist2(p.position, x) })
            .filter(|h| h.dist2 <= r * r)
            .collect();
        match self.mode {
            Mode::BruteForce => {}
            Mode::ExtraFarHit => out.push(Neighbour { index: (self.pts.len() - 1) as u64, dist2: 0.0 }),
            Mode::OutOfRangeHit => out.push(Neighbour { index: self.pts.len() as u64, dist2: 0.0 }),
            Mode::Fails => return Err(PolyError::View { code: "test.storage_failed" }),
        }
        Ok(out)
    }
}

fn fake(pts: &[([f64; 3], Option<[f64; 3]>)], mode: Mode) -> Fake {
    Fake { pts: pts.iter().map(|&(position, normal)| ScanPoint { position, normal }).collect(), mode }
}

#[test]
fn broken_views_are_refused_and_errors_pass_through() {
    let up = Some([0.0, 0.0, 1.0]);
    let down = Some([0.0, 0.0, -1.0]);
    let a = fake(&[([0.0; 3], up)], Mode::BruteForce);
    // The last point is far away; the broken query reports it as a hit anyway (after an
    // incompatible true hit, so the kernel reads on).
    let b = fake(&[([0.0, 0.0, 1e-4], down), ([1.0, 0.0, 0.0], up)], Mode::ExtraFarHit);
    assert_eq!(detect_overlap(&[&a, &b], 1e-3).unwrap_err(), PolyError::Inconsistent);
    let b = fake(&[([1.0, 0.0, 0.0], down), ([1.0, 0.0, 0.0], down)], Mode::OutOfRangeHit);
    let near = fake(&[([1.0, 0.0, 0.0], up)], Mode::BruteForce);
    assert_eq!(detect_overlap(&[&near, &b], 1e-3).unwrap_err(), PolyError::Inconsistent);
    let b = fake(&[([0.0; 3], up)], Mode::Fails);
    let e = detect_overlap(&[&a, &b], 1e-3).unwrap_err();
    assert_eq!(e, PolyError::View { code: "test.storage_failed" });
    assert_eq!(e.code(), "scan.poly.view");
    assert_eq!(e.to_string(), "scan.poly.view: test.storage_failed");

    let nan = fake(&[([f64::NAN, 0.0, 0.0], up)], Mode::BruteForce);
    assert_eq!(invalid_name(detect_overlap(&[&a, &nan], 1e-3).unwrap_err()), "scan.position");
    let huge = fake(&[([2f64.powi(501), 0.0, 0.0], up)], Mode::BruteForce);
    assert_eq!(invalid_name(detect_overlap(&[&a, &huge], 1e-3).unwrap_err()), "scan.position");
    let long = fake(&[([0.0; 3], Some([0.0, 0.0, 2.0]))], Mode::BruteForce);
    assert_eq!(invalid_name(detect_overlap(&[&a, &long], 1e-3).unwrap_err()), "scan.normal");
}

#[test]
fn prefilter_skips_only_scans_beyond_d() {
    // A point exactly d away along one axis from the far corner of the other scan's box:
    // the lower bound equals d*d, so the scan is queried and the tie counts.
    let up = Some([0.0, 0.0, 1.0]);
    let u = 2f64.powi(-10);
    let a = fake(&[([1.0 + u, 0.0, 0.0], up)], Mode::BruteForce);
    let b = fake(&[([0.0; 3], up), ([1.0, 0.0, 0.0], up)], Mode::BruteForce);
    let m = detect_overlap(&[&a, &b], u).unwrap();
    assert_eq!(m.scans[0].sets.scans_of(0).unwrap(), vec![1]);
    assert_eq!(m.scans[1].status, vec![PointStatus::NothingWithinD, PointStatus::Overlapping]);
    // One ulp further is beyond d.
    let a = fake(&[([1.0 + u + f64::EPSILON, 0.0, 0.0], up)], Mode::BruteForce);
    let m = detect_overlap(&[&a, &b], u).unwrap();
    assert_eq!(m.scans[0].status, vec![PointStatus::NothingWithinD]);
}
